//! Native wgpu/Vulkan renderer.
//!
//! No canvas, no JavaScript, no WebView: the swap chain comes from an Android
//! `ANativeWindow`, the block texture array is decoded from the embedded MCRS
//! archive, and the chunk meshes are generated by the Rust world module.

use std::sync::Arc;
use std::time::Instant;

use winit::dpi::PhysicalSize;
use winit::window::Window;

use crate::arena::ChunkArena;
use crate::camera::Camera;
use crate::cull::Frustum;
use crate::input::Input;
use crate::mesh::Vertex;
use crate::textures::BlockTextures;
use crate::world;

const DEPTH_FORMAT: wgpu::TextureFormat = wgpu::TextureFormat::Depth32Float;
const UNIFORM_SIZE: u64 = 256;
const DAY_SECONDS: f32 = 600.0;

pub struct Renderer {
    surface: wgpu::Surface<'static>,
    device: wgpu::Device,
    queue: wgpu::Queue,
    config: wgpu::SurfaceConfiguration,
    pipeline: wgpu::RenderPipeline,
    translucent_pipeline: wgpu::RenderPipeline,
    sky_pipeline: wgpu::RenderPipeline,
    uniform_buffer: wgpu::Buffer,
    bind_group: wgpu::BindGroup,
    textures: BlockTextures,
    arena: ChunkArena,
    visible: Vec<usize>,
    depth_texture: wgpu::Texture,
    depth_view: wgpu::TextureView,
    camera: Camera,
    horizon: [f32; 3],
    start: Instant,
    last_frame: Instant,
    frame_index: u64,
    fps: f32,
    draw_ms: f32,
    first_frame: bool,
}

impl Renderer {
    pub async fn new(window: Arc<Window>) -> Result<Self, String> {
        let size = window.inner_size();
        let width = size.width.max(1);
        let height = size.height.max(1);

        let instance = wgpu::Instance::new(wgpu::InstanceDescriptor {
            backends: wgpu::Backends::VULKAN,
            ..Default::default()
        });
        let surface = instance
            .create_surface(window.clone())
            .map_err(|err| format!("create_surface: {err}"))?;
        let adapter = instance
            .request_adapter(&wgpu::RequestAdapterOptions {
                power_preference: wgpu::PowerPreference::HighPerformance,
                compatible_surface: Some(&surface),
                force_fallback_adapter: false,
            })
            .await
            .map_err(|err| format!("request_adapter: {err}"))?;
        let (device, queue) = adapter
            .request_device(&wgpu::DeviceDescriptor {
                label: Some("mc-native/device"),
                required_features: wgpu::Features::empty(),
                required_limits: wgpu::Limits::downlevel_defaults().using_resolution(adapter.limits()),
                experimental_features: wgpu::ExperimentalFeatures::disabled(),
                memory_hints: wgpu::MemoryHints::Performance,
                trace: wgpu::Trace::Off,
            })
            .await
            .map_err(|err| format!("request_device: {err}"))?;

        let capabilities = surface.get_capabilities(&adapter);
        let format = capabilities
            .formats
            .iter()
            .copied()
            .find(|format| {
                !matches!(
                    format,
                    wgpu::TextureFormat::Bgra8UnormSrgb | wgpu::TextureFormat::Rgba8UnormSrgb
                )
            })
            .unwrap_or(capabilities.formats[0]);
        let mut config = surface
            .get_default_config(&adapter, width, height)
            .ok_or_else(|| "adapter cannot present to this window".to_string())?;
        config.format = format;
        config.present_mode = wgpu::PresentMode::Fifo;
        config.desired_maximum_frame_latency = 2;
        surface.configure(&device, &config);

        let textures = crate::textures::build(&device, &queue);
        let world = world::build();
        let arena = ChunkArena::upload(&device, &queue, &world.meshes);
        let camera = Camera::new(world.spawn, world.spawn_yaw);
        log::info!(
            "native world: {} sections, {} vertices, {} indices",
            arena.len(),
            arena.total_vertices,
            arena.total_indices
        );

        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("mc-native/chunks.wgsl"),
            source: wgpu::ShaderSource::Wgsl(include_str!("shader.wgsl").into()),
        });
        let sky_shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("mc-native/sky.wgsl"),
            source: wgpu::ShaderSource::Wgsl(include_str!("sky.wgsl").into()),
        });

        let uniform_buffer = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("mc-native/camera"),
            size: UNIFORM_SIZE,
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        let bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("mc-native/camera.layout"),
            entries: &[
                wgpu::BindGroupLayoutEntry {
                    binding: 0,
                    visibility: wgpu::ShaderStages::VERTEX | wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Uniform,
                        has_dynamic_offset: false,
                        min_binding_size: None,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 1,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Texture {
                        sample_type: wgpu::TextureSampleType::Float { filterable: true },
                        view_dimension: wgpu::TextureViewDimension::D2Array,
                        multisampled: false,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 2,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Sampler(wgpu::SamplerBindingType::Filtering),
                    count: None,
                },
            ],
        });
        let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("mc-native/camera.bind"),
            layout: &bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: uniform_buffer.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: wgpu::BindingResource::TextureView(&textures.view),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: wgpu::BindingResource::Sampler(&textures.sampler),
                },
            ],
        });
        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("mc-native/chunks.layout"),
            bind_group_layouts: &[Some(&bind_group_layout)],
            immediate_size: 0,
        });
        let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("mc-native/chunks"),
            layout: Some(&pipeline_layout),
            vertex: wgpu::VertexState {
                module: &shader,
                entry_point: Some("vs_main"),
                buffers: &[Some(Vertex::layout())],
                compilation_options: Default::default(),
            },
            fragment: Some(wgpu::FragmentState {
                module: &shader,
                entry_point: Some("fs_main"),
                targets: &[Some(wgpu::ColorTargetState {
                    format: config.format,
                    blend: None,
                    write_mask: wgpu::ColorWrites::ALL,
                })],
                compilation_options: Default::default(),
            }),
            primitive: wgpu::PrimitiveState {
                topology: wgpu::PrimitiveTopology::TriangleList,
                front_face: wgpu::FrontFace::Ccw,
                cull_mode: Some(wgpu::Face::Back),
                ..Default::default()
            },
            depth_stencil: Some(wgpu::DepthStencilState {
                format: DEPTH_FORMAT,
                depth_write_enabled: Some(true),
                depth_compare: Some(wgpu::CompareFunction::Less),
                stencil: wgpu::StencilState::default(),
                bias: wgpu::DepthBiasState::default(),
            }),
            multisample: wgpu::MultisampleState::default(),
            multiview_mask: None,
            cache: None,
        });
        let translucent_pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("mc-native/translucent"),
            layout: Some(&pipeline_layout),
            vertex: wgpu::VertexState {
                module: &shader,
                entry_point: Some("vs_main"),
                buffers: &[Some(Vertex::layout())],
                compilation_options: Default::default(),
            },
            fragment: Some(wgpu::FragmentState {
                module: &shader,
                entry_point: Some("fs_main"),
                targets: &[Some(wgpu::ColorTargetState {
                    format: config.format,
                    blend: Some(wgpu::BlendState::ALPHA_BLENDING),
                    write_mask: wgpu::ColorWrites::ALL,
                })],
                compilation_options: Default::default(),
            }),
            primitive: wgpu::PrimitiveState {
                topology: wgpu::PrimitiveTopology::TriangleList,
                front_face: wgpu::FrontFace::Ccw,
                cull_mode: None,
                ..Default::default()
            },
            depth_stencil: Some(wgpu::DepthStencilState {
                format: DEPTH_FORMAT,
                depth_write_enabled: Some(false),
                depth_compare: Some(wgpu::CompareFunction::Less),
                stencil: wgpu::StencilState::default(),
                bias: wgpu::DepthBiasState::default(),
            }),
            multisample: wgpu::MultisampleState::default(),
            multiview_mask: None,
            cache: None,
        });
        let sky_pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("mc-native/sky"),
            layout: Some(&pipeline_layout),
            vertex: wgpu::VertexState {
                module: &sky_shader,
                entry_point: Some("vs_main"),
                buffers: &[],
                compilation_options: Default::default(),
            },
            fragment: Some(wgpu::FragmentState {
                module: &sky_shader,
                entry_point: Some("fs_main"),
                targets: &[Some(wgpu::ColorTargetState {
                    format: config.format,
                    blend: None,
                    write_mask: wgpu::ColorWrites::ALL,
                })],
                compilation_options: Default::default(),
            }),
            primitive: wgpu::PrimitiveState {
                topology: wgpu::PrimitiveTopology::TriangleList,
                cull_mode: None,
                ..Default::default()
            },
            depth_stencil: Some(wgpu::DepthStencilState {
                format: DEPTH_FORMAT,
                depth_write_enabled: Some(false),
                depth_compare: Some(wgpu::CompareFunction::Always),
                stencil: wgpu::StencilState::default(),
                bias: wgpu::DepthBiasState::default(),
            }),
            multisample: wgpu::MultisampleState::default(),
            multiview_mask: None,
            cache: None,
        });

        let (depth_texture, depth_view) = create_depth(&device, width, height);
        let now = Instant::now();
        Ok(Self {
            surface,
            device,
            queue,
            config,
            pipeline,
            translucent_pipeline,
            sky_pipeline,
            uniform_buffer,
            bind_group,
            textures,
            arena,
            visible: Vec::new(),
            depth_texture,
            depth_view,
            camera,
            horizon: [0.47, 0.63, 0.84],
            start: now,
            last_frame: now,
            frame_index: 0,
            fps: 0.0,
            draw_ms: 0.0,
            first_frame: false,
        })
    }

    pub fn width(&self) -> u32 {
        self.config.width
    }

    pub fn height(&self) -> u32 {
        self.config.height
    }

    pub fn resize(&mut self, size: PhysicalSize<u32>) {
        if size.width == 0 || size.height == 0 {
            return;
        }
        self.config.width = size.width;
        self.config.height = size.height;
        self.surface.configure(&self.device, &self.config);
        let (depth_texture, depth_view) =
            create_depth(&self.device, self.config.width, self.config.height);
        self.depth_texture = depth_texture;
        self.depth_view = depth_view;
    }

    pub fn render(&mut self, input: &mut Input) {
        let now = Instant::now();
        let dt = (now - self.last_frame).as_secs_f32();
        self.last_frame = now;
        self.fps = if dt > 0.0 { 1.0 / dt } else { 0.0 };
        self.camera.update(input, dt);

        let aspect = self.config.width.max(1) as f32 / self.config.height.max(1) as f32;
        let view_projection = self.camera.view_projection(aspect);
        let eye = self.camera.eye();
        let elapsed = (now - self.start).as_secs_f32();
        let time = (0.20 + elapsed / DAY_SECONDS).fract();
        let sky = sky_state(time);

        let mut uniform = [0u8; UNIFORM_SIZE as usize];
        uniform[0..64].copy_from_slice(&crate::math::to_bytes(&view_projection));
        uniform[64..128].copy_from_slice(&crate::math::to_bytes(&crate::math::invert(
            &view_projection,
        )));
        let mut write4 = |slot: usize, value: [f32; 4]| {
            let offset = slot * 16;
            for (i, component) in value.iter().enumerate() {
                uniform[offset + i * 4..offset + i * 4 + 4]
                    .copy_from_slice(&component.to_le_bytes());
            }
        };
        write4(8, [eye[0], eye[1], eye[2], 0.0]);
        write4(9, [sky.horizon[0], sky.horizon[1], sky.horizon[2], 1.0]);
        let view_blocks = (world::WORLD_RADIUS * world::SECTION) as f32;
        write4(
            10,
            [
                view_blocks * 0.55,
                view_blocks * 0.98,
                elapsed,
                sky.intensity,
            ],
        );
        write4(11, [sky.sun_dir[0], sky.sun_dir[1], sky.sun_dir[2], sky.day]);
        write4(12, [sky.zenith[0], sky.zenith[1], sky.zenith[2], 1.0]);
        write4(13, [sky.horizon[0], sky.horizon[1], sky.horizon[2], 1.0]);
        write4(14, [sky.sun_color[0], sky.sun_color[1], sky.sun_color[2], 1.0]);
        write4(15, [0.0, 0.0, 0.0, 0.0]);
        self.queue.write_buffer(&self.uniform_buffer, 0, &uniform);
        self.horizon = sky.horizon;

        let frustum = Frustum::from_view_projection(&view_projection);
        let view_sq = view_blocks * view_blocks;
        self.visible.clear();
        for (index, slot) in self.arena.slots.iter().enumerate() {
            if slot.index_count == 0 || !frustum.intersects_aabb(slot.min, slot.max) {
                continue;
            }
            let cx = (slot.min[0] + slot.max[0]) * 0.5 - eye[0];
            let cy = (slot.min[1] + slot.max[1]) * 0.5 - eye[1];
            let cz = (slot.min[2] + slot.max[2]) * 0.5 - eye[2];
            if cx * cx + cy * cy + cz * cz > view_sq {
                continue;
            }
            self.visible.push(index);
        }

        let frame = match self.surface.get_current_texture() {
            wgpu::CurrentSurfaceTexture::Success(frame) => frame,
            wgpu::CurrentSurfaceTexture::Suboptimal(frame) => {
                drop(frame);
                self.surface.configure(&self.device, &self.config);
                return;
            }
            wgpu::CurrentSurfaceTexture::Timeout | wgpu::CurrentSurfaceTexture::Occluded => return,
            wgpu::CurrentSurfaceTexture::Outdated | wgpu::CurrentSurfaceTexture::Lost => {
                self.surface.configure(&self.device, &self.config);
                return;
            }
            wgpu::CurrentSurfaceTexture::Validation => return,
        };
        let swap_view = frame
            .texture
            .create_view(&wgpu::TextureViewDescriptor::default());
        let mut encoder = self
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                label: Some("mc-native/frame"),
            });
        {
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("mc-native/world"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &swap_view,
                    depth_slice: None,
                    resolve_target: None,
                    ops: wgpu::Operations {
                        load: wgpu::LoadOp::Clear(wgpu::Color {
                            r: self.horizon[0] as f64,
                            g: self.horizon[1] as f64,
                            b: self.horizon[2] as f64,
                            a: 1.0,
                        }),
                        store: wgpu::StoreOp::Store,
                    },
                })],
                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                    view: &self.depth_view,
                    depth_ops: Some(wgpu::Operations {
                        load: wgpu::LoadOp::Clear(1.0),
                        store: wgpu::StoreOp::Store,
                    }),
                    stencil_ops: None,
                }),
                timestamp_writes: None,
                occlusion_query_set: None,
                multiview_mask: None,
            });
            pass.set_pipeline(&self.sky_pipeline);
            pass.set_bind_group(0, &self.bind_group, &[]);
            pass.draw(0..3, 0..1);

            pass.set_pipeline(&self.pipeline);
            pass.set_bind_group(0, &self.bind_group, &[]);
            for &index in &self.visible {
                let slot = &self.arena.slots[index];
                if slot.opaque_index_count == 0 {
                    continue;
                }
                pass.set_vertex_buffer(0, slot.vertex_buffer.slice(..));
                pass.set_index_buffer(slot.index_buffer.slice(..), wgpu::IndexFormat::Uint32);
                pass.draw_indexed(0..slot.opaque_index_count, 0, 0..1);
            }

            pass.set_pipeline(&self.translucent_pipeline);
            pass.set_bind_group(0, &self.bind_group, &[]);
            for &index in &self.visible {
                let slot = &self.arena.slots[index];
                if slot.index_count <= slot.opaque_index_count {
                    continue;
                }
                pass.set_vertex_buffer(0, slot.vertex_buffer.slice(..));
                pass.set_index_buffer(slot.index_buffer.slice(..), wgpu::IndexFormat::Uint32);
                pass.draw_indexed(slot.opaque_index_count..slot.index_count, 0, 0..1);
            }
        }
        self.queue.submit(Some(encoder.finish()));
        self.queue.present(frame);

        self.frame_index += 1;
        if self.frame_index % 120 == 0 {
            log::info!(
                "frame {}: {:.1} fps, {} sections visible, {}/{} tris",
                self.frame_index,
                self.fps,
                self.visible.len(),
                self.arena.total_indices / 3,
                self.arena.total_indices / 3
            );
        }
        self.first_frame = true;
    }
}

fn create_depth(
    device: &wgpu::Device,
    width: u32,
    height: u32,
) -> (wgpu::Texture, wgpu::TextureView) {
    let texture = device.create_texture(&wgpu::TextureDescriptor {
        label: Some("mc-native/depth"),
        size: wgpu::Extent3d {
            width: width.max(1),
            height: height.max(1),
            depth_or_array_layers: 1,
        },
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: DEPTH_FORMAT,
        usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
        view_formats: &[],
    });
    let view = texture.create_view(&wgpu::TextureViewDescriptor::default());
    (texture, view)
}

struct SkyState {
    zenith: [f32; 3],
    horizon: [f32; 3],
    sun_color: [f32; 3],
    sun_dir: [f32; 3],
    intensity: f32,
    day: f32,
}

fn smoothstep(edge0: f32, edge1: f32, x: f32) -> f32 {
    let t = ((x - edge0) / (edge1 - edge0)).clamp(0.0, 1.0);
    t * t * (3.0 - 2.0 * t)
}

fn mix3(a: [f32; 3], b: [f32; 3], t: f32) -> [f32; 3] {
    [
        a[0] + (b[0] - a[0]) * t,
        a[1] + (b[1] - a[1]) * t,
        a[2] + (b[2] - a[2]) * t,
    ]
}

fn sky_state(time: f32) -> SkyState {
    let angle = time * std::f32::consts::TAU;
    let elevation = angle.sin();
    let day = smoothstep(-0.08, 0.24, elevation);
    let sunset = (1.0 - elevation.abs() / 0.30).clamp(0.0, 1.0) * day.max(0.15);

    let night_zenith = [0.010, 0.018, 0.052];
    let night_horizon = [0.030, 0.052, 0.105];
    let day_zenith = [0.30, 0.54, 1.00];
    let day_horizon = [0.70, 0.83, 1.00];

    let mut zenith = mix3(night_zenith, day_zenith, day);
    let mut horizon = mix3(night_horizon, day_horizon, day);
    zenith = mix3(zenith, [0.35, 0.26, 0.46], sunset * 0.30);
    horizon = mix3(horizon, [1.00, 0.42, 0.18], sunset * 0.70);

    let sun_color = mix3([1.0, 0.42, 0.16], [1.0, 0.95, 0.86], day);
    let sun_dir = [angle.cos() * 0.82, elevation, angle.cos() * 0.36];
    let length = (sun_dir[0] * sun_dir[0] + sun_dir[1] * sun_dir[1] + sun_dir[2] * sun_dir[2])
        .sqrt()
        .max(0.001);
    SkyState {
        zenith,
        horizon,
        sun_color,
        sun_dir: [
            sun_dir[0] / length,
            sun_dir[1] / length,
            sun_dir[2] / length,
        ],
        intensity: 0.16 + 0.84 * day,
        day,
    }
}
